package com.primehr.rsp.selection.domain;
import com.primehr.shared.exception.*;import org.junit.jupiter.api.Test;import java.time.*;import static org.assertj.core.api.Assertions.*;
class SelectionDomainTest{
 @Test void lifecycleRequiresDecisionIndependentApprovalAndImmutableFinalization(){SelectionCase value=selection("APPROVER");assertThatThrownBy(()->value.submit("PREPARER",Instant.now())).isInstanceOf(IllegalLifecycleTransitionException.class);value.decide(SelectionCase.Outcome.SELECTED,"CANDIDATE","Merit selection",null,null,null);value.submit("PREPARER",Instant.now());assertThatThrownBy(()->value.approve("PREPARER",false,null,Instant.now())).isInstanceOf(IllegalLifecycleTransitionException.class);value.approve("APPROVER",false,null,Instant.now());value.finalizeCase("FINALIZER",Instant.now());assertThat(value.getStatus()).isEqualTo(SelectionCase.Status.FINALIZED);assertThatThrownBy(()->value.decide(SelectionCase.Outcome.NO_SELECTION,null,"Changed",null,null,null)).isInstanceOf(IllegalLifecycleTransitionException.class);}
 @Test void administratorExceptionRequiresReason(){SelectionCase value=selection("APPROVER");value.decide(SelectionCase.Outcome.NO_SELECTION,null,"No appointment",null,null,null);value.submit("PREPARER",Instant.now());assertThatThrownBy(()->value.approve("OTHER",true,null,Instant.now())).isInstanceOf(IllegalArgumentException.class);value.approve("OTHER",true,"Acting appointing authority designation",Instant.now());assertThat(value.getAdministratorExceptionReason()).isNotBlank();}
 @Test void offerResponseIsOwnedFinalAndIdempotent(){OfferResponse offer=new OfferResponse("A","S","APP","PERSON",Instant.now().plusSeconds(3600));offer.respond(OfferResponse.Status.ACCEPTED,"key-1",null,Instant.now());assertThatCode(()->offer.respond(OfferResponse.Status.ACCEPTED,"key-1",null,Instant.now())).doesNotThrowAnyException();assertThatThrownBy(()->offer.respond(OfferResponse.Status.DECLINED,"key-2",null,Instant.now())).isInstanceOf(ApplicationConflictException.class);}
 private static SelectionCase selection(String approver){return new SelectionCase("A","P","V","E","a".repeat(64),"M",1,null,approver,Instant.now().plusSeconds(3600),"You were selected.","The selection is complete.","{}","b".repeat(64));}
}
